-- ============================================================
-- חלק 37ב: התקנון ומדיניות הפרטיות — הנוסח המלא והמעודכן
--
-- מחליף את התבנית של חלק 37 (20261019440000) בנוסח המלא שנמסר, כלשונו
-- ועם שבירות השורות (כותרת, כותרות סעיפים ופסקאות). המשתנים {{store_name}},
-- {{store_email}}, {{store_phone}} מוחלפים באתר בכל הצגה בפרטי העסק של
-- אותה חנות (site_settings) — כך כל מסמך מיוחס ל-Tenant שלו.
--
--  1. legal_default_html(key) — התבנית החדשה (זהה ל-DEFAULT_TERMS_HTML /
--     DEFAULT_PRIVACY_HTML שנבנים מ-src/lib/legal-templates.ts; בדיקת יחידה משווה).
--  2. legal_fill_default_pages() — חנויות קיימות: נוסח ריק, הנוסח הקצר
--     הישן (חלק 16א) או התבנית של חלק 37 — שלא נערכו — מקבלים את הנוסח המלא.
--     נוסח שבעל החנות כתב / ערך — לא נוגעים בו.
--  3. חנות חדשה — הטריגר מחלק 37 (site_settings_legal_defaults) משתמש
--     ב-legal_default_html, ולכן מקבלת את הנוסח החדש כבר בהקמה.
--
-- ניתן להרצה חוזרת.
-- ============================================================
BEGIN;
SET LOCAL client_min_messages = warning;

CREATE OR REPLACE FUNCTION public.legal_default_html(_key text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $fn$
  SELECT CASE _key
    WHEN 'terms' THEN $tpl$<h2>תקנון האתר - {{store_name}}</h2><p>הנך מתבקש לקרוא תקנון זה במלואו ובעיון, כתנאי מוקדם להתקשרות בין הצדדים. החנות משמשת לרכישת מוצרים על ידי ציבור הגולשים באינטרנט בישראל ורשאים לרכוש בה בני 18 ומעלה, בעלי תא דואר אלקטרוני ברשת האינטרנט בישראל ובעל כתובת מגורים בישראל, אשר ברשותם כרטיס אשראי תקף בישראל. תנאי מוקדם לתוקף זכייתו של משתתף ברכישה הוא אישור חברת כרטיסי האשראי לעיסקה ולגביה. גלישה בחנות ו/או רכישת המוצר ו/או שירות המוצעים למכירה בו, מהווה את הסכמתך לקבל ולנהוג על פי הוראות התקנון. לפיכך אם אינך מסכים לתנאי מתנאי תקנון זה, הנך מתבקש לא לעשות כל שימוש בחנות. המחיר הינו כולל מע"מ אלא אם צויין מפורשות אחרת.</p><h3>רכישה רגילה</h3><p>במכירה רגילה מוצעים למכירה כמות מוגבלת של מוצרים במחיר קבוע מראש. הליך המכירה יתבצע בתנאים כדלקמן: החנות תציג רשימת מוצרים לרבות כל הפרטים אודות המוצר או השירות המוצע למכירה ואת המחיר כפי שנקבע מראש, המכירה הינה עד גמר המלאי. לאחר הוספת המוצרים המבוקשים ל"עגלת הקניות" ימשיך הקונה בעמוד "עגלת הקניות" ל"אישור קנייה" ושם ימלא את פרטיו המלאים ולאחר מכן יסתיים הליך הקנייה האינטרנטי. השלמת הליך המכירה יבוצע לאחר אימות העיסקה בטלפון תוך 24 שעות (של יום עסקים) ממועד ביצוע ההזמנה, לחילופין ההזמנה תושלם אוטומטית.</p><h3>החלפת מוצר</h3><p>החלפת מוצר באמצעות חשבונית תוך 14 ימים בלבד. החזר כספי יינתן כחוק לפי אמצעי התשלום בו הלקוח שילם. בגין ביטול עסקה ינוכו 5% או 100 ₪ מערך העסקה לפי הנמוך מביניהם. הזיכוי הינו אישי ולא ניתן להעברה או למכירה. החלפת פריט בשווי ערכו בעת ההחלפה. במקרה וחזר המוצר ויש נזק על הלקוח לשלם על הנזק.</p><h3>ביטול הזמנה</h3><p>ככלל הלקוח רשאי לבטל את העיסקה בכפוף ובהתאם להוראות חוק הגנת הצרכן התשמ"א 1981. ניתן לבטל רכישת מוצר 14 יום מיום קבלת המוצר. הביטול יעשה אך ורק בהודעה שתשלח בכתב ו/או באמצעות הדואר האלקטרוני ישירות אל החנות בכתובת: {{store_email}}. במקרה של ביטול העיסקה יחוייב הלקוח בשיעור של 5% אך לא למעלה מ-100 ש"ח, בהתאם להוראות החוק. אם סופק המוצר ללקוח, חלה על הלקוח חובת החזרת המוצר אל החנות עצמה. מוסכם כי הלקוח יחזיר את המוצר באריזתו, שלם וללא פגיעה ו/או נזק ו/או פגם מכל מין וסוג שהוא. מוסכם כי הלקוח יחוייב בתשלום מלא בגין דמי משלוח, במידה והמוצר כבר נשלח ללקוח. החנות תהא רשאית לבטל עיסקה אם נפלה טעות קולמוס או כוח עליון. הודעה על ביטול תימסר לקונים בטלפון או בדואר אלקטרוני.</p><h3>אספקת המוצרים</h3><p>החנות תדאג לאספקת המוצר שהוזמן לכתובת כפי שהוקלדה על ידי הלקוח, תוך המועד הנקוב בדף המכירה, אלא אם צויין אחרת ולאחר אישור חברת האשראי על העסקה. החנות ו/או הספקים לא יהיו אחראים לאיחור בביצוע אספקת המוצר במקרים של כוח עליון (מלחמה, פעולות איבה, נזקי טבע ושביתה). זמני אספקת המוצרים כוללים רק ימי עסקים (א'-ה') לא כולל שישי שבת וערבי חג. זמן אספקה עד 10 ימי עסקים. איסוף עצמי במידה והמוצר מוכן אפשר לאסוף בין השעות 17:00-23:00.</p><h3>דמי משלוח</h3><p>דמי המשלוח אינם כלולים במחיר המוצר. אם ברצונו של הלקוח לשדרג את סוג המשלוח הוא יעשה זאת בעמוד עגלת הקניות ומחיר זה יתווסף לסכום לתשלום. הלקוח יהיה רשאי לאסוף את המוצר ישירות מהחנות בתיאום מראש וללא דמי משלוח.</p><h3>שירות לקוחות</h3><p>כל שאלה או בירור לגבי המוצרים המוצגים באתר ניתן לפנות אל: טלפון: {{store_phone}} דוא"ל: {{store_email}}.</p><h3>שירות כללי</h3><p>התמונות המוצגות באתר הן להמחשה בלבד, ואינן מחייבות את החנות. החנות לא תהא אחראית להרכבתם ו/או התקנתם של מוצרים שנרכשו ואחריות זו תחול על הלקוח ועל חשבונו. כל מידע ו/או תצוגה המופיעים באתר הנם בבעלותה הבלעדית של החנות. אין להעתיק או להפיץ תכנים ללא הסכמה.</p>$tpl$
    WHEN 'privacy' THEN $tpl$<h2>מדיניות פרטיות - {{store_name}}</h2><h3>עקרונות</h3><p>מדיניות זו מסבירה כיצד נאסף, נשמר, נעשה שימוש ונמסר מידע אישי באתר (להלן: "האתר"). "מידע אישי" ו"עיבוד" כהגדרתם בחוק הגנת הפרטיות.</p><h3>סוגי המידע שנאסף</h3><p>פרטי זיהוי ויצירת קשר: שם, דוא"ל, טלפון, כתובת משלוח/חיוב. פרטי הזמנה ותשלום (פרטי כרטיס אשראי מעובדים ע"י ספקי סליקה מורשים; האתר אינו שומר פרטי כרטיס מלאים). מידע טכני ושימושי: כתובת IP, מזהי מכשיר/עוגיות. העדפות שיווקיות ותכתובות שירות.</p><h3>איך נאסף המידע</h3><p>ישירות מהלקוח בעת הרשמה/ביצוע הזמנה/יצירת קשר. אוטומטית באמצעות עוגיות. מצדדים שלישיים: Google Analytics וייתכן שימוש ב-Facebook וב-TikTok למדידה ופרסום ממוקד. ניתן לנהל/למחוק עוגיות דרך הגדרות הדפדפן.</p><h3>מטרות העיבוד</h3><p>ניהול חשבון והזמנות; מתן תמיכה ושירות לקוחות (באמצעות מייל {{store_email}} וטלפון {{store_phone}}). עמידה בהתחייבויות חוזיות ומשפטיות. אבטחה, מניעת הונאה, ניתוח שימושיות ושיווק מותאם.</p><h3>מסירת מידע לצדדים שלישיים</h3><p>ספקי שירות כמעבדי נתונים: סליקה, לוגיסטיקה, מערכות דיוור.</p><p>פלטפורמת החנות "Nuri1" - המידע נשמר ומעובד גם על גבי פלטפורמת Nuri1 המשמשת כתשתית טכנולוגית להפעלת החנות ("מעבד נתונים").</p><h3>אבטחת מידע ושמירת מידע</h3><p>נוקטים אמצעים ארגוניים וטכניים סבירים להגנה על המידע. נשמור מידע כל עוד נחוץ למטרות שלשמן נאסף.</p><h3>זכויותיך</h3><p>זכות לעיון במידע האישי המעובד עליך, לתיקון או למחיקה של מידע. מחיקת חשבון תבוצע לאחר פנייה לבעל האתר באמצעות פרטי יצירת הקשר.</p><h3>קטינים ועדכונים למדיניות</h3><p>האתר אינו מיועד לשימוש ע"י קטינים מתחת לגיל 18. נעדכן מדיניות זו מעת לעת וגרסה עדכנית תפורסם באתר.</p>$tpl$
  END
$fn$;
GRANT EXECUTE ON FUNCTION public.legal_default_html(text) TO anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.legal_fill_default_pages()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  -- נוסחים קודמים שלא נערכו (חלק 16א, חלק 37) — כ"טביעת אצבע": בלי תגיות ורווחים
  old_terms CONSTANT text[] := ARRAY[$old$מבוא:תקנוןזהמהווההסכםמשפטימחייב...תנאירכישה:הרכישהמותרתלבני18ומעלה,בעליכרטיסאשראיישראליתקף.המחיריםכולליםמע"מ.אישורעסקאות:הנהלתהאתרשומרתזכותלאימותטלפוניתוך24שעות.ביטוליםוהחזרות:ביטוליתאפשרתוך14ימיםמקבלתהמוצרכחוק.ינוכודמיביטולבשיעור5%או100₪(הנמוךמביניהם).אספקהומשלוחים:אספקהתבוצעתוך[10]ימיעסקים(א'-ה').איסוףעצמיבתיאוםמראשבין[17:00-23:00].יצירתקשר:טלפון[050-0000000],דוא"ל[example@email.com].$old$, $old$תקנוןאתר{{store_name}}הנךמתבקשלקרואתקנוןזהבמלואוובעיון,כתנאימוקדםלהתקשרות.החנותמשמשתלרכישתמוצריםעלידיבני18ומעלה,בעלידואראלקטרוניוכתובתבישראל,וכרטיסאשראיתקף.רכישהמהווההסכמהלתקנון.המחירכוללמע"מ.בעלהאתר:האתרוהחנותמופעליםומנוהליםעלידי{{store_name}}(ח.פ./ע.מ{{business_id}}),האחראיהבלעדילמוצרים,למכירות,לאספקהולשירות.פלטפורמתהמסחרשעליהפועלהאתרמשמשתספקיתטכנולוגיהבלבדואינהצדלעסקאותבאתר.רכישהוביטול:הרכישההינהעדגמרהמלאי.הלקוחרשאילבטלאתהעיסקהבכפוףלהוראותחוקהגנתהצרכן(14יוםמקבלתהמוצר),בהודעהלכתובתהדוא"ל:{{store_email}}.בגיןביטולינוכו5%או100₪(הנמוךמביניהם).חובתהחזרתהמוצרחלהעלהלקוח(באריזתוהמקורית,שלםוללאנזק).הלקוחיחויבבדמיהמשלוחאםהמוצרכברנשלח.אספקהומשלוחים:אספקתהמוצרלכתובתהלקוחעד10ימיעסקים(א'-ה'),לאחראישורחברתהאשראי.החנותאינהאחראיתלאיחורבגיןכוחעליון(מלחמה,שביתה,נזקיטבע).יצירתקשר:לבירוריםניתןלפנותטלפוניתל-{{store_phone}}אולדוא"ל{{store_email}}.אחריותההתקנהחלהעלהלקוח.התמונותלהמחשהבלבד.$old$]::text[];
  old_privacy CONSTANT text[] := ARRAY[$old$1.עקרונות:מדיניותזומסבירהכיצדנאסףמידעאישי.2.מידענאסף:פרטיזיהוי,מידעטכניופרטיהזמנה.פרטיאשראיאינםנשמרים.3.איסוףושימוש:אוטומטיתאומהלקוח,לצורךהשירותושיפורו.4.צדדיםשלישיים:המידעעשוילעבורלספקישירותולפלטפורמתNuri1.פרטיאשראייועברורקלחברתהסליקה.5.שמירתמידע:שמירהכלעודהמידענחוץ.6.זכויותיך:עיוןומחיקהע"יפנייהלשירותהלקוחות.לאמיועדלקטינים.$old$, $old$מדיניותפרטיות-{{store_name}}החברהמכירהבחשיבותהשמירהעלפרטיותהמשתמשיםבאתר.שימושךוביצוערכישהמהוויםהסכמתךלשימושבמידעשייאסף.סליקהואשראי:בעלהעסקמתחייבכיפרטיהאשראישלהלקוחלאיעברולצדג',למעטלמסוףהסליקהולחברתהאשראי.מאגרימידע:המידעשיימסריישמרבמאגריהמידע.החברהרשאיתלעשותבושימושלצורךטיפולבהזמנותושיפורהשירות,וכןלפנותאליךבהצעותשיווקיות(דיוורישיר).הינךרשאיבכלעתלפנותלשירותהלקוחותב-{{store_email}}ולבקשהסרהמרשימתהתפוצה.$old$]::text[];
  v_terms integer;
  v_privacy integer;
BEGIN
  UPDATE public.site_settings
     SET terms_content = public.legal_default_html('terms')
   WHERE btrim(coalesce(terms_content, '')) = ''
      OR public.legal_text_fingerprint(terms_content) = ANY (old_terms);
  GET DIAGNOSTICS v_terms = ROW_COUNT;
  UPDATE public.site_settings
     SET privacy_content = public.legal_default_html('privacy')
   WHERE btrim(coalesce(privacy_content, '')) = ''
      OR public.legal_text_fingerprint(privacy_content) = ANY (old_privacy);
  GET DIAGNOSTICS v_privacy = ROW_COUNT;
  RETURN v_terms + v_privacy;
END
$fn$;
REVOKE ALL ON FUNCTION public.legal_fill_default_pages() FROM PUBLIC, anon, authenticated;

SELECT public.legal_fill_default_pages();

COMMIT;
